SELECT * FROM r_pan_file_cleanup_task
WHERE execution_state IN ('PENDING','RETRY','PROCESSING')
  AND next_delivery_at <= #{now}
  AND (execution_state != 'PROCESSING' OR lease_until IS NULL OR lease_until <= #{now})
ORDER BY next_delivery_at,task_id LIMIT #{limit}

mapper.update:
UPDATE r_pan_file_cleanup_task
SET delivery_attempts=delivery_attempts+1, delivery_state='PENDING',
    next_delivery_at=#{next}, updated_at=#{now}
WHERE task_id=#{taskId} AND delivery_attempts=#{attempts} AND next_delivery_at <= #{now}
  AND execution_state IN ('PENDING','RETRY','PROCESSING')
  AND (execution_state != 'PROCESSING' OR lease_until IS NULL OR lease_until <= #{now})

UPDATE r_pan_file_cleanup_task
SET delivery_state='SENT''PENDING',
    last_error=#{error},
    updated_at=#{now}
WHERE task_id=#{taskId} AND delivery_attempts=#{attempts}

  AND execution_state IN ('PENDING','RETRY') AND execution_attempts=#{executionAttempts}

UPDATE r_pan_file_cleanup_task
SET execution_state='SUCCEEDED',lease_owner=NULL,lease_until=NULL,last_error=NULL,
    completed_at=#{now},updated_at=#{now}
WHERE task_id=#{taskId} AND execution_state='PROCESSING' AND lease_owner=#{owner}

UPDATE r_pan_file_cleanup_task
SET execution_state=#{state},last_error=#{error},next_delivery_at=#{next},
    delivery_state='PENDING',lease_owner=NULL,lease_until=NULL,updated_at=#{now}
WHERE task_id=#{taskId} AND execution_state='PROCESSING' AND lease_owner=#{owner}

UPDATE r_pan_file_cleanup_task
SET execution_state='MANUAL',last_error=#{error},lease_owner=NULL,lease_until=NULL,updated_at=#{now}
WHERE task_id=#{taskId} AND execution_state != 'SUCCEEDED'
